import { SiteHeader } from '@/react/components/site/SiteHeader'
import { ProofBlock } from '@/react/components/site/ProofBlock'
import { AsciiTrail } from '@/react/components/visuals/AsciiTrail'
import { PlaygroundHero } from '@/react/components/blocks/PlaygroundHero'
import { FeaturesBlock } from '@/react/components/blocks/FeaturesBlock'
import { WhyBlock } from '@/react/components/blocks/WhyBlock'
import { HowItWorksBlock } from '@/react/components/blocks/HowItWorksBlock'
import { CaseStoriesBlock } from '@/react/components/blocks/CaseStoriesBlock'
import { PricingPanelsBlock } from '@/react/components/blocks/PricingPanelsBlock'
import { FaqBlock } from '@/react/components/blocks/FaqBlock'
import { CloseBlock } from '@/react/components/blocks/CloseBlock'
import { SiteFooter } from '@/react/components/blocks/SiteFooter'
import { homeContent, homeSections, type HomeBlocks, type HomeContent, type HomeSection } from '@/lib/pages/home'
import { pageSections } from '@/lib/image'
import { Fragment, type ReactNode } from 'react'
import { cn } from '@/react/lib/cn'
import type { HeaderMenus } from '@/lib/site-header'

// The site's home (app/page.tsx, which renders app/v2/page.tsx), from library items in the site's order: the ASCII
// trail behind the page (a mouse leaves it), the header,
// the playground hero, the proof row, the features, the reasons, the set-up steps beside the MCP session, the case
// stories, the pricing strip, the questions, the close among the creatives and the footer. Each block carries its own
// copy (lib/home/*); `content` replaces the header, proof row, questions and footer (lib/pages/home.ts). `blocks`
// passes each block its own data, pictures included; `sections` lists the sections to show, in order (hero, proof,
// features, why, steps, stories, pricing, faq, close): leave one out to omit it.
export interface HomePageProps {
  content?: HomeContent
  /** Each block's data, pictures included: hero, features, why, steps, stories, pricing, close. */
  blocks?: HomeBlocks
  /** The header menus' content, pictures included (the live card's `picture`, the use cases' `shots`); Acme by default. */
  menus?: HeaderMenus
  /** The sections to show, in order; all of them in the site's order by default. */
  sections?: readonly HomeSection[]
  className?: string
}

const WRAP = 'mx-auto w-full max-w-[calc(var(--ds-layout-content)+2*var(--ds-layout-gutter))] px-(--ds-layout-gutter)'

export function HomePage({ content: c = homeContent, blocks: b = {}, menus, sections, className }: HomePageProps) {
  const parts: Record<HomeSection, ReactNode> = {
    hero: <PlaygroundHero session={b.hero?.session} />,
    proof: <ProofBlock title={c.proof.title} logos={c.proof.logos} />,
    features: <FeaturesBlock ads={b.features?.ads} burst={b.features?.burst} ring={b.features?.ring} tally={b.features?.tally} />,
    why: <WhyBlock creatives={b.why?.creatives} logo={b.why?.logo} />,
    steps: <HowItWorksBlock session={b.steps?.session} />,
    stories: <CaseStoriesBlock cases={b.stories?.cases} quotes={b.stories?.quotes} />,
    pricing: <PricingPanelsBlock sets={b.pricing?.sets} />,
    faq: (
      <div className={cn(WRAP, 'py-(--ds-layout-section)')}>
        <FaqBlock id="home-faq" title={c.faq.title} body={c.faq.lead} action={c.faq.action} items={c.faq.items} />
      </div>
    ),
    close: <CloseBlock creatives={b.close?.creatives} />,
  }
  return (
    <div data-ds="home-page" className={cn('bg-surface text-fg', className)}>
      <AsciiTrail mode="page" />
      <SiteHeader menus={menus} links={c.header.nav} secondary={c.header.secondary} cta={c.header.cta} />
      <main id="main">
        {pageSections(homeSections, sections).map((k) => <Fragment key={k}>{parts[k]}</Fragment>)}
      </main>
      <SiteFooter columns={c.footer.columns} legal={c.footer.legal} />
    </div>
  )
}

export default HomePage

// The home page's copy (site app/v2/page.tsx: the header, the proof row, the questions and the footer; each section's
// own copy lives with its block in lib/home/). The questions are the site's own; the marks, customers and links are
// Acme placeholders. Both flavors read this file.

import type { BurstContent } from '@/lib/home/accounts-burst'
import type { CloseCreative } from '@/lib/home/close'
import type { MediaAd, RingContent, TallyContent } from '@/lib/home/features'
import type { PanelCreative } from '@/lib/home/pricing'
import type { SessionContent } from '@/lib/home/session'
import type { StoryCase, StoryQuote } from '@/lib/home/stories'
import type { WhyCreative } from '@/lib/home/why'

const nav = [
	{ label: 'Products', href: '/products' },
	{ label: 'Use cases', href: '/use-cases' },
	{ label: 'Enterprise', href: '/enterprise' },
	{ label: 'Resources', href: '/resources' },
	{ label: 'Pricing', href: '/pricing' },
]

export const homeContent = {
	header: { nav, secondary: { label: 'Sign in', href: '/sign-in' }, cta: { label: 'Get a free API key', href: '/sign-up', short: 'Get API key' } },
	proof: { title: 'Trusted by teams and agents at', logos: [{ name: 'Acme' }, { name: 'Acme Labs' }, { name: 'Acme Studio' }, { name: 'Acme Goods' }, { name: 'Acme Air' }, { name: 'Acme & Co' }] as { name: string; src?: string; ratio?: number; height?: number }[] },
	faq: {
		title: 'Frequently asked questions',
		lead: 'Anything else is in the docs, with every endpoint and tool.',
		action: { label: 'Read the docs', href: '/docs' },
		items: [
			{ q: 'How do credits work?', a: 'Most calls cost one credit per record returned: one brand, one creator or one creative. A search that returns 50 posts or ads uses 50 credits. The API and the MCP server draw on the same monthly credits, and a request that fails is never billed.' },
			{ q: 'What does Spyglass index?', a: 'Organic posts on Instagram and TikTok with their views, likes and comments, Meta ads across Facebook and Instagram placements, and the landing pages the ads link to. Brands and creators sit on one record across all of them. Google Ads, LinkedIn Ads and Pinterest are coming next.' },
			{ q: 'Can I see how organic posts perform?', a: 'Yes. Every Instagram and TikTok post comes with its views, likes and comments, and an outlier score against its own account’s usual. Rank a brand’s or a whole category’s posts by any of them, without its ads mixed in.' },
			{ q: 'How fresh is the data?', a: 'Spyglass watches public data continuously and keeps it, so ads that stopped running are still there. For an account that is not indexed yet, a live lookup fetches its latest posts in about 10 to 30 seconds and starts indexing the rest.' },
			{ q: 'Should I use the MCP server or the REST API?', a: 'Use the MCP server to ask in Claude, ChatGPT, Cursor or any MCP client. You sign in with your browser, no API key needed. Use the REST API to call Spyglass from your own code, with SDKs for Python and Node, and a CLI. Both reach the same data and credits.' },
			{ q: 'What if a brand I need is not indexed?', a: 'Add it. Send its website or Instagram handle, up to 20 at a time, and Spyglass indexes it automatically. Adding an account and checking its status are free.' },
			{ q: 'What is analyzed before I ask?', a: 'Every creative is tagged ahead of time for hook, angle, persona, format and funnel stage. Ask for a brand’s top hooks, personas, angles or media mix across the last 90 days and the answer is already computed.' },
			{ q: 'What happens when I run out of credits?', a: 'Free stops until next month. On Creator you can buy more at $2 per 1K credits, and Pro continues at $1.50 per 1K. Nothing is queued or partly charged in between.' },
		],
	},
	footer: {
		legal: '© 2026 Acme Inc.',
		columns: [
			{ title: 'Products', wide: true, links: [{ label: 'Brands and creators', href: '/products/brands' }, { label: 'Media archive', href: '/products/media' }, { label: 'Collaborations', href: '/products/collabs' }, { label: 'Coming soon', href: '/products/coming-soon' }] },
			{ title: 'Use cases', wide: true, links: [{ label: 'Paid ads', href: '/use-cases/paid' }, { label: 'Organic social', href: '/use-cases/organic' }, { label: 'Creator sourcing', href: '/use-cases/creators' }] },
			{ title: 'Resources', links: [{ label: 'Templates', href: '/templates' }, { label: 'Docs', href: '/docs' }, { label: 'Blog', href: '/blog' }] },
			{ title: 'Company', links: [{ label: 'Enterprise', href: '/enterprise' }, { label: 'Talk to us', href: '/contact' }, { label: 'Sign in', href: '/sign-in' }] },
			{ title: 'Legal', links: [{ label: 'Terms', href: '/terms' }, { label: 'Privacy', href: '/privacy' }] },
		],
	},
}

export type HomeContent = typeof homeContent

/** The home's sections in the site's order; pass `sections` to reorder them or leave some out. */
export const homeSections = ['hero', 'proof', 'features', 'why', 'steps', 'stories', 'pricing', 'faq', 'close'] as const
export type HomeSection = (typeof homeSections)[number]

/** Each block's own data, pictures included (Acme placeholders where left out). */
export interface HomeBlocks {
	/** The hero's MCP session (its creatives as images). */
	hero?: { session?: SessionContent }
	/** The features: the media strip's ads, the searches (each with `images`), the graph ring and the tally. */
	features?: { ads?: MediaAd[]; burst?: BurstContent; ring?: RingContent; tally?: TallyContent }
	/** The reasons: the archive's four creatives and the advertiser's mark. */
	why?: { creatives?: WhyCreative[]; logo?: string }
	/** The set-up steps' MCP session. */
	steps?: { session?: SessionContent }
	/** The case stories: each case's picture, and the quotes. */
	stories?: { cases?: StoryCase[]; quotes?: StoryQuote[] }
	/** The pricing strip's sets of five creatives. */
	pricing?: { sets?: PanelCreative[][] }
	/** The creatives the close cycles through. */
	close?: { creatives?: CloseCreative[] }
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

